code.ERC223Token.allowance(address,address):
function allowance( address owner, address spender ) public constant returns (uint256 remaining) {
 return allowances_[owner][spender];
 }

code.ERC223Token.approve(address,uint256):
function approve( address spender, uint256 value ) public returns (bool success) {
 allowances_[msg.sender][spender] = value;
 Approval( msg.sender, spender, value );
 return true;
 }

code.ERC223Token.approveAndCall(address,uint2:
function approveAndCall( address spender, uint256 value, bytes context ) public returns (bool success) {
 if ( approve(spender, value) ) {
 tokenRecipient recip = tokenRecipient( spender );
 recip.receiveApproval( msg.sender, value, context );
 return true;
 }
 return false;
 }

code.ERC223Token.transfer(address,uint256,byt:
function transfer(address to, uint value, bytes data, string custom_fallback ) public returns (bool success) {
 _transfer( msg.sender, to, value, data );
 if ( isContract(to) ) {
 ContractReceiver rx = ContractReceiver( to );
 require(rx.call.value(0)(bytes4(keccak256(custom_fallback)), msg.sender, value, data) );
 }
 return true;
 }

function transfer( address to, uint value, bytes data ) public returns (bool success) {
 if (isContract(to)) {
 return transferToContract( to, value, data );
 }
 _transfer( msg.sender, to, value, data );
 return true;
 }

code.ERC223Token.ERC223Token(uint256,string,u:
function ERC223Token( uint256 initialSupply, string tokenName, uint8 decimalUnits, string tokenSymbol ) public {
 totalSupply = initialSupply * 10 ** uint256(decimalUnits);
 balances_[msg.sender] = totalSupply;
 name = tokenName;
 decimals = decimalUnits;
 symbol = tokenSymbol;
 }

code.ERC223Token.burn(uint256):
function burn( uint256 value ) public returns (bool success) {
 require( balances_[msg.sender] >= value );
 balances_[msg.sender] -= value;
 totalSupply -= value;
 Burn( msg.sender, value );
 return true;
 }

code.ERC223Token.balanceOf(address):
function balanceOf( address owner ) public constant returns (uint) {
 return balances_[owner];
 }

code.ERC223Token.isContract(address):
function isContract( address _addr ) private constant returns (bool) {
 uint length;
 assembly { length := extcodesize(_addr) }
 return (length > 0);
 }

code.ERC223Token..transfer(address,address,ui:
function _transfer( address from, address to, uint value, bytes data ) internal {
 require( to != 0x0 );
 require( balances_[from] >= value );
 require( balances_[to] + value > balances_[to] );
 balances_[from] -= value;
 balances_[to] += value;
 bytes memory empty;
 empty = data;
 Transfer( from, to, value );
 }

code.ERC223Token.transferToContract(address,u:
function transferToContract( address to, uint value, bytes data ) private returns (bool success) {
 _transfer( msg.sender, to, value, data );
 ContractReceiver rx = ContractReceiver(to);
 rx.tokenFallback( msg.sender, value, data );
 return true;
 }

code.ERC223Token.transferFrom(address,address:
function transferFrom( address from, address to, uint256 value ) public returns (bool success) {
 require( value <= allowances_[from][msg.sender] );
 allowances_[from][msg.sender] -= value;
 bytes memory empty;
 _transfer( from, to, value, empty );
 return true;
 }

code.ERC223Token.transfer(address,uint256):
function transfer(address to, uint256 value) public {
 bytes memory empty;
 _transfer(msg.sender, to, value, empty);
 }

code.ERC223Token.burnFrom(address,uint256):
function burnFrom( address from, uint256 value ) public returns (bool success) {
 require( balances_[from] >= value );
 require( value <= allowances_[from][msg.sender] );
 balances_[from] -= value;
 allowances_[from][msg.sender] -= value;
 totalSupply -= value;
 Burn( from, value );
 return true;
 }
